  const TITRE = { 1: 'bank', 2: 'staff', 3: 'cog', 4: 'percent', 5: 'crane', 6: 'handcoin', 7: 'swap' };
  const forTitre = t => TITRE[t] ? icon(TITRE[t]) : '';
  return { icon, forText, forMission, forTitre, names: Object.keys(ICONS) };
